-- ============================================================
-- Ereb4c (3/3): Günə-özəl push bildirişlərinin AR tərcüməsi
-- pregnancy_day_notifications + mommy_day_notifications — Azure/gpt-5.6-sol
-- ƏVVƏL sxem faylı (sütunlar) işlədilməlidir.
-- ============================================================

UPDATE public.mommy_day_notifications AS x SET title_ar = v.t, body_ar = v.b
FROM (VALUES
  ('0c893825-691b-4509-9849-6369336b84d4'::uuid, 'فنان يمزق لوحته 🖍️', 'هل لم يعجبه الخط الذي رسمه، فمزق الورقة ورماها قائلًا: «هذا سيئ»؟ لقد بدأ لديه شعور بالنقد الذاتي والسعي إلى الكمال! قولي له: «لنجرب لونًا مختلفًا في المرة القادمة»، وحوّلي خيبة أمله إلى فرصة للاستكشاف.'),
  ('bcac5731-4815-4adc-beb4-861e3ff078b1', 'التمسّح بكِ مثل قطة 🐾', 'هل يمشي هذا الصباح على أطرافه الأربعة، ويتمسّح بساقكِ ولا يقول سوى «مياو»؟ بدلًا من الوقوف وإلقاء القواعد عليه، قدّمي له أنتِ أيضًا وعاء حليب خياليًا. فاللعب دائمًا أسهل وأكثر متعة من التوبيخ.'),
  ('51ca75c5-97b8-4826-b323-ca25f125a567', 'ألّا تشرحي شيئًا لأحد 📝', 'ألا يرى أحد مدى تعبكِ في المنزل، وهذا يجعلكِ على وشك الانفجار؟ افتحي مفكرة المزاج. اكتبي فيها كل ما أثار غضبكِ اليوم. تقبّل مشاعركِ والتعبير عنها بالكتابة سيساعدكِ أكثر.'),
  ('989e82d9-dbab-4ad4-8fb4-42a6025e0511', 'ساعة القراءة الصامتة 📖', 'لا قراءة هذا المساء. شغّلي موسيقى خلفية هادئة من الحكايات الهادفة، واكتفيا بتأمل الصور بصمت. سيتعب دماغ طفلكِ بصريًا، وسيستسلم للنوم من دون أن تنطقي بكلمة واحدة.'),
  ('6f490476-47fe-4d7a-adc6-bf02e33e53bc', 'اختبار صندوق الدفع في المتجر 🛒', 'هل يصرخ طلبًا للشوكولاتة أمام صندوق الدفع مباشرة؟ لا تستسلمي رغم نظرات الواقفين خلفكِ. افتحي قائمة التسوق وقولي: «إنها غير موجودة هنا، ولن يقرأها صندوق الدفع». إذا تمسكتِ بقراركِ، فسيتراجع هو أيضًا.'),
  ('851d1060-8f2e-4d29-b181-eb135eec18ca', 'الأكل بالفم بدلًا من اليدين 🐶', 'هل يريد أن يأكل من الطبق كالقطط من دون استخدام يديه؟ لا تمنعيه. سيتّسخ المطبخ على أي حال، فدعيه يتقمص دور القطة لمدة 5 دقائق. هذا اللعب التمثيلي المضحك هو أكثر الطرق مرحًا للتغلب على فقدان الشهية.'),
  ('9555c57b-eea5-4d41-a55f-827af2218674', 'تدليك الكتفين من الأب 💆‍♂️', 'لقد وقفتِ طويلًا اليوم، ويكاد ظهركِ ينكسر من الركض خلف طفلكِ وجمع الألعاب عن الأرض. ما إن ينام، اطلبي من زوجكِ تدليك كتفيكِ لمدة 10 دقائق. أنتِ محرّك المنزل، ولا بد أن تستعيدي طاقتكِ.'),
  ('ac3ac13e-8fa6-42b2-ace2-92fa2336b5eb', 'الظلام التام في الغرفة 🌌', 'ألا يستطيع النوم بسبب الضوء المتسلل من الممر؟ إنه يبحث عن الظروف المثالية. أغلقي الباب بإحكام واجعلي الغرفة مظلمة تمامًا، ودعي الميلاتونين يؤدي دوره الطبيعي ليساعده على النوم سريعًا.'),
  ('e268e86b-b622-447e-800e-69d444728521', 'أزمة «إنه لي» 🧸', 'هل يحتضن جهاز التحكم في المنزل ويقول: «هذا لي!»؟ إنه يختبر حدود الملكية. لا تصفيه بالأنانية، بل قولي: «شكرًا لأنك وجدته من أجلي»، ثم استعيديه مع توجيه انتباهه إلى لعبة أخرى.'),
  ('e71d30e6-0cdb-4938-b907-fc93e194b4d5', 'معنى الجمل غير المكتملة 🗣️', 'عندما ينسى كلمة، هل يشير بيديه وينتظر منكِ أن تخمّنيها؟ أكملي جملته بصبر، وراقبي ملامح الارتياح على وجهه. فبدعمكِ له، يبني حصيلته اللغوية وثقته بنفسه بهذه الطريقة.'),
  ('6dda8fe5-3765-4d3c-bdfe-6519fcf2d0a0', 'كارثة مساعدتكِ في المطبخ 🧑‍🍳', 'بينما كنتِ تفردين العجين، هل جاء ووضع كرسيه وأصرّ على سكب الدقيق بنفسه؟ سيبكي إن لم تسمحي له. أعطيه وعاءً بلاستيكيًا صغيرًا وقليلًا من الدقيق. ستعمّ الفوضى المطبخ، لكن غروره سيشعر بالرضا.'),
  ('776040ef-af05-4430-a752-3b380b194dba', 'القمر يركض أمامنا 🌕', 'عندما تعودان بالسيارة مساءً، هل ينظر من النافذة ويقول إن القمر يتبعكما؟ إنه يظن أن الكون يدور حوله. شاركيه اللعبة من دون أن تحطّمي خياله، وقولي: «ترى إلى أين سيأتي معنا؟».'),
  ('58e2fe84-f6c5-40ff-93ab-26ea06ad9f14', 'عشق القميص المتّسخ 👕', 'هل يرتدي القميص نفسه منذ 3 أيام ولا يسمح لكِ بغسله؟ في هذا العمر، تمنحهم بعض الأشياء شعورًا بالأمان. لا تجادليه، بل خذيه منه بحكاية خيالية قائلةً: «أرسلته في مغامرة سحرية داخل الغسالة، وسيعود أقوى». سيصدّق هذا الخيال.'),
  ('b740d6be-007b-4aa6-9c46-6ffbce8b157e', 'مراسم حداد على نملة 🐜', 'هل توقف عن الحركة في الحديقة لأنه رأى نملة على الأرض، وأخذ يبكي ظنًا منه أنها تائهة؟ تعاطفه لا يعرف حدودًا. قولي له إن أمها ستأتي الآن لتأخذها.'),
  ('fcc60573-09e9-4a7c-8399-55df532828cd', 'الضوضاء البيضاء في المستنقع 🌊', 'هل يقفز من مكان إلى آخر بدلًا من النوم في غرفته؟ شغّلي من تطبيق قياس الصوت صوت أمواج بحر قوية أو ضوضاء بيضاء في الخلفية. سيبدّد ذلك التردد الرتيب طاقته الجامحة، وستُغمض عيناه خلال 10 دقائق.'),
  ('73abbd29-9b2f-4f48-8461-6482853b741f', 'مساعدة كارثية بالمكنسة 🧹', 'بينما ترتّبين المنزل، هل يأتي قائلًا: «سأفعل ذلك»، ثم ينثر الأوساخ أكثر في الغرفة؟ ستقوم القيامة إن لم تسمحي له. أعطيه منديلًا مبللًا وقولي: «أنت مسؤول عن هذه الزاوية من الطاولة فقط». وهكذا تنجزين عملكِ ويشعر غروره بالرضا أيضًا.'),
  ('eacaec53-45d2-4b70-9f52-8b48878bd78c', 'وقت التحديق في الجدار الفارغ 🛋️', 'هل يلعب وحده في الغرفة؟ أرجوكِ، لا تذهبي لاستغلال تلك اللحظة في غسل الأطباق! اجلسي على الأريكة، وخذي كوب الشاي بيدكِ، وحدّقي في الجدار فحسب. نعم، من دون التفكير في أي شيء. دوّني في مذكّرة مزاجكِ: «5 دقائق من السلام». أنتِ بحاجة إلى ذلك.'),
  ('f172b5bc-02ec-44a8-9df7-fcc0cfb0c0e3', 'دراما «شعري انكسر!» 🪮', 'هل يهرب فور رؤية المشط قائلًا إن شعره يؤلمه؟ حساسيته الحسية تخيفه. شتّتي انتباهه. أعطيه مرآة وقولي: «لنرَ من سيُخرج لسانه بطريقة أظرف أمام المرآة؟»، وبينما هو منشغل، مشّطي شعره بسرعة وانتهي.'),
  ('9632825c-5c1a-41f6-900b-2b6b7e88d644', 'رفض ارتداء المعطف 🧥', 'هل يرفض ارتداء المعطف الشتوي لأن الشمس ساطعة في الخارج؟ افتحي قسم الطقس والملابس، وأريه على الهاتف رمز الطفل الذي يرتدي ملابس شتوية. انقلي القاعدة إلى الشاشة الرقمية وتنحّي جانبًا، وسيرتدي معطفه بهدوء.'),
  ('6f53d579-a4b1-4e03-8f30-fcdd7a9084bf', 'فضفضة بالهمس في الظلام 🌙', 'أطفئي أضواء الغرفة تمامًا. استلقي بجانبه، واهمسي في أذنه بصوت خافت جدًا عمّا حدث خلال اليوم، أو عن أكثر صفة تحبينها في شخصيته. فالهمس من أكثر الطرق سحرًا لتهيئة الدماغ للنوم.'),
  ('ba2db9df-7097-4890-b7eb-8938c592806f', 'كذبة «هذا ليس خطئي» 🤥', 'هل سكب الماء على الأرض عمدًا، ثم أشار بإصبعه إلى سيارته وقال: «هي التي دفعته»؟ هذا ليس كذبًا، بل آلية دفاع. قولي له: «هيا نعلّم السيارة أيضًا كيف تنظّف المكان»، وبذلك تتجاوزين الموقف بذكاء.'),
  ('ce02bfea-edc6-42ad-80fd-37f3c322993b', 'قواعد الزحليقة في الحديقة 🤝', 'هل دفع طفلًا آخر عند الزحليقة لأنه أراد أن ينزلق قبله؟ لا تضربي طفلكِ بدافع الإحراج. ذكّريه بالقاعدة بصوت لطيف لكن حازم: «حان دوره الآن، ثم يأتي دورك». هكذا سيتعلّم القواعد الاجتماعية.'),
  ('2128fd31-18d2-4020-9903-1e4bdb06a192', 'حتى لا تبكي البيضة 🍳', 'هل أشفق على البيضة عندما كسرتِها ورفض أكلها؟ إن تعاطفه بلا حدود. أنقذي الموقف فورًا بحكاية لطيفة من خيالكِ، مثل: «ستعيش الآن في عضلاتك وتجعلك قويًا».'),
  ('2fbf236d-dcf9-462e-911e-87f8e16831b1', 'قواعد ترتيب الوسائد 🛏️', 'هل يبكي لأنه يريد ضبط الوسادة بدقة متناهية؟ لقد بدأت لديه طقوس مرتبطة بالنوم. سايريه، ورتّبي الوسادة كأنكِ قستِها بالمسطرة، ثم أطفئي الأنوار بحزم لتمنحيه شعورًا بالأمان.'),
  ('3b18406f-7fbc-4193-88c1-aa910648f2b5', 'أعيدي إليّ القمامة التي رميتِها! 🗑️', 'هل أقام الدنيا لأنكِ رميتِ غلاف الشوكولاتة القديم الذي كان يحتفظ به؟ قد يكون قمامة بالنسبة إليكِ، لكنه كنز بالنسبة إليه. شتّتي انتباهه بلعبة أخرى لامعة.'),
  ('3d6e1c1c-6a73-4824-ae1e-d09852574023', 'ديكتاتور المنزل على المائدة 👑', 'هل يتحكّم في أماكن الجلوس على مائدة الإفطار قائلًا: «لا تجلسي هناك، اجلسي هنا»؟ من دون كسر إرادته بعنف، حافظي على التوازن والسلام في الغرفة بابتسامة صغيرة وقولي: «حسنًا، ليكن كما تريد».'),
  ('c6026760-e985-429a-b39f-d4d1786df630', 'مختبر صغير في حوض الاستحمام 🛀', 'هل يخلط أنواعًا من الصابون بألوان مختلفة في الماء ليحضّر جرعة سحرية؟ نعم، سيغرق الحمّام بالفوضى، لكنه يتعلّم كيف تذوب المواد. هذا الاستكشاف العلمي أجمل وسيلة لتخفيف تعب المساء وتهيئته لنوم هادئ.'),
  ('40e041b4-2484-475f-93b5-25cda3ee362e', 'مسرحية «من أنتِ؟» 🎭', 'هل ينظر إليكِ كأنكِ غريبة ويقول: «من أنتِ؟ أين أمي؟» هذه لعبة أدوار جديدة. قولي له: «أنا الطبيبة، جئت لأستمع إلى قلبك»، ثم دغدغيه. ودعي الغرفة تضجّ بالضحك منذ الصباح.'),
  ('417e0bcc-cf3b-4a96-95e9-58a2f51764f6', 'فن ورق المرحاض 🧻', 'هل دخلتِ الغرفة فوجدتِ ورق المرحاض كله مفكوكًا ومنتشرًا في أنحاء المنزل؟ بدلًا من الغضب، اجمعي الأوراق واصنعا منها كرة معًا. تغلّبي على الفوضى بالإبداع والضحك، لا بالصراخ.'),
  ('4a1de341-603c-4aae-ab4d-439d7bb05d7c', 'متعة الصمت 🤫', 'أخيرًا نام. هل عمّ المنزل صمت شديد لدرجة أنكِ تسمعين طنينًا في أذنيكِ؟ افتحي مقياس الصوت في التطبيق. إن النظر إلى عبارة 0 ديسيبل سيكون أفضل تدليك بصري في العالم لدماغكِ المتعب والمثقل بالضجيج.'),
  ('3d9dcc3e-1698-4fca-951e-a58aed0724d2', 'لون الكوب غير مناسب 🥤', 'هل قامت القيامة في الغرفة لأنكِ قدّمتِ الماء في الكوب الأصفر؟ لا تبالغي في التفكير، فهو يختبر حدودكِ هذا الصباح فحسب. اسكبي الماء فورًا في الكوب الأزرق، وأعيدي السلام إلى الغرفة لتحافظي على طاقتكِ.'),
  ('522145b2-4826-4821-80c0-e0e180045415', 'مجرد ضمّه إلى صدركِ 🫂', 'هل دفعكِ اليوم حقًا إلى الجنون واستنزف طاقتكِ؟ لكنه يبدو بريئًا جدًا وهو نائم في سريره... أطفئي الأنوار ولا تقرئي له حكاية. استلقي إلى جواره، واستنشقي بعمق رائحة الطفولة النقية، واحمدي الله.'),
  ('792e3525-032e-4662-ba49-1276a3b3ef78', 'حكايات أمهات أخريات 💬', 'لا تشعري بالإحباط عندما تفتحين إنستغرام وترين أطفال الجميع مثاليين! أغلقي ذلك التطبيق وادخلي إلى مجتمع Anacan. خذي نفسًا عميقًا عندما ترين أن بيوت الجميع تعمّها الفوضى مثل بيتكِ تمامًا.'),
  ('3e4bbd84-ef8f-45a2-b630-5aeadd95390e', 'استقلالية «لا تمسكي بيدي!» 🚶‍♂️', 'هل يفلت يدكِ في الطريق ويريد أن يمشي بمفرده؟ إذا كان المكان آمنًا، فدعيه يختبر استقلاليته. ما عليكِ سوى السير خلف هذا المتمرّد الصغير الحر بخطوتين، ومراقبته بفخر واعتزاز.'),
  ('4c96a8e1-971d-4b98-9e5c-faff2c2726a9', 'هجمة فلسفية مفاجئة 🤔', 'هل فاجأكِ بسؤال علمي مثل: لماذا قاع البحر مظلم؟ لا تقلقي! افتحي Anacan AI واحصلي على ألطف إجابة بأسلوب قصصي يناسب فهمه في هذا العمر، ومعتمدة من أطباء الأطفال وعلماء النفس، ثم اقرئيها له. أنتِ الأم التي تعرف كل شيء دائمًا!'),
  ('9f289ae7-fe30-4b1a-8ebd-63874521363d', 'لعبة المطاردة في الغرفة المظلمة 🔦', 'حان وقت النوم، لكن طاقته لا تنفد؟ أطفئي جميع أضواء الغرفة، وخذي مصباحًا يدويًا صغيرًا، والعبي معه لعبة «لنرَ مَن سيلحق به الضوء على الحائط». فاللعب في الظلام سيسرّع إفراز الميلاتونين ويساعده أيضًا على تفريغ طاقته.'),
  ('d28d5d46-d2a6-4daa-b454-adbdf6be3f63', 'ألم الجرح غير المرئي 🩹', 'لا يوجد شيء في إصبعه، لكنه يبكي ويقول إنه جُرح ويطلب ضمادة لاصقة؟ هذا ليس ألمًا جسديًا، بل هو بحاجة إلى حنانكِ. ضعي له الضمادة وقبّليه، وقولي إنكِ شفيته بقبلة سحرية. وهكذا ستنقذين يومكما.'),
  ('19ac1700-7f02-47aa-b9e8-f8064c7e18d0', 'إغلاق الباب والمساحة الشخصية 🚪', 'هل دخل غرفته وأغلق الباب خلفه وقال لكِ ألا تأتي؟ لا تنزعجي. إنه يريد فقط أن ينعزل قليلًا عن الضوضاء والفوضى ليستريح. ما دام بأمان، فدعيه يستمتع بمساحته الشخصية. إنه يكبر!'),
  ('2cb51eab-cbdc-48ba-8569-e245d61ad27e', 'أعذار الليل التي لا تنتهي 🚰', 'تكاد عيناه تُغمضان، لكنه يقفز فجأة قائلًا: قدمي تحكني، أريد ماءً؟ إنه أستاذ في تأجيل النوم. اضبطي مؤقتًا، وقولي له إن جميع الأعذار تذهب إلى النوم عندما يرن الهاتف. امنحي الهاتف سلطة إعلان النهاية، وانسحبي أنتِ من المعادلة.'),
  ('9240add5-52c7-45dc-8ae0-15dd7dadfa88', 'هذا ليس اسمي 📛', 'هل يقول لكِ: لا تناديني باسمي، أنا الرجل العنكبوت؟ إنه يستكشف هويته. سايريه! قدّمي له فطوره قائلة: تفضل يا سيد الرجل العنكبوت. بيدكِ أن تحوّلي التوتر في الغرفة إلى موقف مضحك خلال ثوانٍ.'),
  ('2127b5f4-7e9a-438e-9094-bd9d7f0d5237', 'حيلة قائمة التسوق في المتجر 🛒', 'هل طالب فجأة بالحلوى أمام صندوق الدفع؟ لا تكترثي إطلاقًا لنظرات الآخرين التي تتساءل أي نوع من الأمهات أنتِ. افتحي قائمة التسوق وقولي: ليست موجودة في القائمة، لذا لن يبيعها لنا صندوق الدفع، وتمسّكي بقراركِ.'),
  ('73af2e7a-1bb5-4576-8888-801050bfada3', 'الألوان تجاوزت الورق إلى الجدار 🖍️', 'هل دخلتِ الغرفة ووجدتِ لوحة جدارية جديدة؟ خذي نفسًا عميقًا. لقد تجاوز حدود الورق ليختبر مهاراته الحركية على نطاق واسع. قبل أن تمسحي هذه التحفة، التقطي لها صورة بالتأكيد كي تريها له في المستقبل وتضحكا معًا.'),
  ('ba708130-cef9-4b08-8a17-7c16cb66de0a', 'لا يريد الخروج من المنزل ⛅', 'المنزل في فوضى، وهو يبكي على الأريكة ويقول إنه لن يخرج؟ افتحي معلومات الطقس والملابس وتحققي من درجة الحرارة الفعلية في الخارج، ثم ألبسيه ملابس مناسبة وخذيه إلى الحديقة حتى لو اضطررتِ إلى الإصرار. ما إن يلامس الهواء النقي وجهه حتى يتلاشى كل غضبه.'),
  ('c3fe5fd9-dde9-47f5-b95c-98d26881d393', 'عندما يصبح بطل الحكاية 🪄', 'افتحي الحكايات الذكية، واستبدلي اسم بطل الحكاية مباشرةً باسم طفلكِ. وخلال الحكاية، اقرئي كيف نام ذلك البطل بشجاعة وهدوء واستمع إلى الكلام. عندما يسمع نفسه جزءًا من الحكاية، سيغمض عينيه دون أي اعتراض.'),
  ('139226ae-9370-42b4-954a-012623528599', 'بكاء غامض في منتصف الليل 😭', 'هل استيقظ في منتصف الليل باكيًا وعيناه مغمضتان ولا يستجيب لكِ؟ تحققي باستخدام تحليل البكاء؛ فعلى الأرجح أنه ذعر ليلي. حاولي ألا توقظيه، واكتفي بالبقاء بجانبه وإمساك يده. سيهدأ من تلقاء نفسه ويعود إلى النوم.'),
  ('a18289d8-27fc-49de-ad3f-5cb7e1e5a6a1', 'وقت الأم السري لتناول الشوكولاتة 🍫', 'هل تختبئين خلف الخزانة لتأكلي الشوكولاتة بعيدًا عن عينيه؟ هنيئًا لكِ! فهذا الغلوكوز حق طبيعي لكِ لتتحملي أسئلته التي لا تنتهي وصراخه، ولتستعيدي طاقتكِ. لا تلومي نفسكِ على ذلك أبدًا.'),
  ('a4aa4ea2-4391-40e9-ab29-3d2dca2ff6fe', 'مطاردة الظل 🏃‍♂️', 'هل يندفع فجأة أثناء سيركما في الشارع محاولًا الإمساك بظله؟ خياله يتفوق على منطقه. لا تمنعيه، بل انضمي أنتِ أيضًا إلى هذه اللعبة المجنونة والمرحة في وسط الشارع، وحاولي الإمساك بظلكِ. فالحياة أقصر من أن نأخذها بجدية مفرطة.'),
  ('4d4b704f-57d5-4f72-9df3-13398bb1f2e3', 'متلازمة الحذاء المعكوس 👟', 'هل ارتدى الحذاء الأيمن في قدمه اليسرى، والأيسر في قدمه اليمنى، ولا يسمح لكِ بتصحيح الأمر؟ اتركيه كما هو! ففخره بأنه ارتداه بنفسه وشعوره بالاستقلال أهم بمليون مرة من ارتداء الحذاء بالطريقة الصحيحة.'),
  ('95ee8df4-a59a-42f4-b252-bf062304f70b', 'تفريغ غضبي رقميًا 📝', 'ألا يرى أحد مدى تعبكِ اليوم، وتشعرين أن الابتسام يخنقكِ؟ افتحي يوميات الحالة المزاجية. أفرغي على الشاشة كل ما بداخلكِ من مشاعر مؤلمة وإرهاق. أن تكتبي «لقد استُنزفت طاقتي» سيساعدكِ على التعافي أسرع من التظاهر بالكمال.'),
  ('ec907054-781c-4e3c-be06-6c97119a4864', 'تدليك الكتفين من الأب 💆‍♂️', 'لقد أمضيتِ اليوم وقتًا طويلًا واقفة، ويكاد ظهركِ ينكسر من الركض خلف طفلكِ وجمع الألعاب عن الأرض. ما إن ينام، اطلبي من شريككِ تدليك كتفيكِ لمدة 10 دقائق. أنتِ محرّك هذا المنزل، ولا بد للمحرّك أن يرتاح ويستعيد طاقته.'),
  ('f6ed5025-5dc3-4f4a-8ce2-d48478e2666f', 'تأكيد الصمت على الشاشة 📉', 'أخيرًا نام. هل ما زالت أصوات الصراخ ترنّ في أذنيكِ؟ افتحي مقياس الصوت. ستمنحكِ مراقبة ذلك الخط وهو ينخفض إلى 0 ديسيبل في الغرفة أجمل تدليك بصري لذهنكِ المتعب والمثقل.'),
  ('48318bc7-c4f3-4717-9848-18bd10967e29', 'حكاية الأب المرتجلة 🦸‍♂️', 'هل بحّ صوتكِ ولا ترغبين في قراءة الكتاب؟ أوكلي مهمة الحكاية إلى الأب. دعيه يروي قصة خيالية وعبثية يكون طفلكِ بطلها. استلقي مسترخية بجوار الحائط، واستمتعي بمشاهدة طفلكِ وهو يضحك من قلبه مع أبيه.'),
  ('4ac93f87-372d-4d1a-a449-a2da763a8227', 'شكل هذا الطعام سيئ 🥒', 'هل دفع الطبق بعيدًا لأنكِ قطّعتِ الخيار طوليًا بدلًا من تقطيعه إلى دوائر؟ ذائقته الجمالية تجاه الطعام في طور التشكّل. تعلّمي كيف تُخفين الخضار نفسها في أشكال مرحة. ستفوزين في لعبة التصميم هذه.'),
  ('61167ef0-dce7-4186-9b36-5aa8a00936ff', 'الهروب إلى الحمّام طلبًا للعزلة 🛀', 'هل ظلّ متشبثًا بساقكِ طوال اليوم حتى أنهككِ اللمس المتواصل؟ الشعور بالاكتفاء من اللمس حقيقي. اتركيه في الغرفة، وادخلي الحمّام لمدة 5 دقائق، وأغلقي الباب وخذي أنفاسكِ فحسب. أنتِ بحاجة إلى استعادة طاقتكِ.'),
  ('a897741a-cd22-4371-a712-b1ae3911676e', 'أغانيه التي يؤلفها بنفسه 🎤', 'لم تشرق الشمس بعد، لكنه يقفز ويغني بصوت مرتفع كلمات بلا معنى؟ لا تصرخي في وجهه لإسكاته. الطفل الذي يبدأ صباحه بالغناء يفرّغ توتره وعدوانيته. شاركيه تلك الطاقة المجنونة لمدة 1 دقيقة، وسيطير النعاس من عينيكِ فورًا.'),
  ('ad4460c3-33b8-4fdc-85b5-ca63eae32f6e', 'الأمهات المثاليات على Instagram 📱', 'هل شعرتِ بالإحباط فور فتح Instagram ورؤية منازل الجميع المرتبة وأطفالهم الهادئين؟ احذفي ذلك التطبيق! انضمّي إلى مجتمع Anacan. اقرئي قصص الأمهات الحقيقيات اللواتي تشبه بيوتهن الفوضوية وأطفالهن العنيدون بيتكِ وطفلكِ، واطمئني.'),
  ('b2cba04d-e6f3-4afd-a54a-7b8bbbf1f6e4', 'النوم الذي يأتي مع الهمس 🤫', 'هل يهرب من السرير ويقفز من مكان إلى آخر؟ اخفضي صوتكِ فجأة حتى يكاد يختفي. ابدئي بالتحدث همسًا وبصوت خافت جدًا. سيضطر إلى تركيز انتباهه جسديًا ليفهمكِ، وسيتعب دماغه خلال 5 دقائق وينتقل إلى وضع النوم. جرّبي!'),
  ('1dcf070f-1d18-4228-b248-9ed1c6174aff', 'لعبة عُثر عليها في الثلاجة 🧊', 'هل فتحتِ الثلاجة فوجدتِ داخلها سيارة مطاطية؟ هذه لعبة لاختبار الذاكرة ووضع الأشياء في أماكن مختلفة. لا تغضبي، فهذا التصرف العبثي جزء من نموه.'),
  ('486ad622-5eff-484f-8ea8-ea64a245ed91', 'لماذا قشّرتِ أنتِ الموزة؟! 🍌', 'هل انقلبت الغرفة رأسًا على عقب لأنكِ قشّرتِ الموزة؟ القاعدة الذهبية في هذا العمر: يجب أن يقرر هو كل شيء. لا يمكنكِ إعادة قشرة الموزة إلى مكانها، لذا أعطيه فورًا موزة جديدة ودعيه يقشّرها بالطريقة التي يريدها. العناد معه لن يؤدي إلا إلى إضاعة وقتكِ.'),
  ('b59a06d3-66eb-4eef-8c37-b58f8b3331ca', 'صمتكما كزوجين 🥂', 'نام طفلكِ وأصبح المنزل مرتبًا. اجلسي إلى جوار زوجكِ على الأريكة، ولا تشغّلا التلفاز حتى. فقط تبادلا نظرة تقول: نجحنا في هذا أيضًا، وما زلنا على قيد الحياة. هذه هي أكثر لحظات الأبوة والأمومة رومانسية وواقعية كفريق واحد.'),
  ('c8f0d464-17b3-4dc7-a4f5-c03c96c8a18b', 'البيت الصغير تحت الطاولة ⛺', 'هل دخل طفلكِ تحت طاولة الطعام وبنى لنفسه بيتًا، ويريد تناول الغداء هناك؟ كوني مرنة قليلًا في القواعد. ناوليه الحساء إلى ذلك المكان المظلم. فتغيير المكان قادر على تحفيز شهية حتى أكثر الأطفال عزوفًا عن الطعام، بفضل شعور المغامرة.'),
  ('1f9be131-7868-4433-adc0-efe09d70723d', 'أنتِ لا تلعبين معي! 😠', 'بينما كنتِ تنظرين إلى هاتفكِ، جاء وأدار وجهكِ نحوه بيديه وكأنه يقول: انظري إليّ!؟ وهو محق. فهو لا يريد مجرد وجودكِ بجانبه، بل يريد اهتمامكِ الكامل دون تشتت. ضعي الهاتف جانبًا، وحافظي على التواصل البصري الكامل معه لمدة 3 دقائق، وسيهدأ فورًا.'),
  ('86f2c2e9-f758-416c-a78d-b431eb3db53a', 'بهلوان على حافة الرصيف 🧱', 'هل يصرّ طفلكِ في طريقكما إلى الحديقة على المشي فوق أضيق حافة للرصيف بدلًا من الطريق المستوي؟ أمسكي بذراعه لحمايته ودعيه يتغلب على هذا التحدي الصغير. فالتوازن والثقة بالنفس يتطوران معًا بصورة رائعة، فلا تمنعيه.'),
  ('963db29c-a2ad-4233-bbc2-364a68692feb', 'المؤثرات الصوتية في الغرفة 🪄', 'هل سئمتِ القراءة هذا المساء؟ شغّلي القصص الذكية. وأثناء سرد القصة، اصنعي مسرحًا صوتيًا في الغرفة بتقليد صرير الباب وصوت الرياح والهمسات. ستجذب هذه المؤثرات الصوتية غير المألوفة انتباهه فورًا إلى قلب الحكاية.'),
  ('2d56a8b7-4b19-4fb3-95e9-798ee0cfa5d6', 'خطة السباق لمغادرة الحديقة 🌳', 'حان وقت العودة من الحديقة وبدأت نوبات البكاء. لن يفيدكِ سحبه بالقوة. قولي له: لنرَ من سيصل إلى السيارة أولًا وهو يقفز كالأرنب؟ ووجّهي انتباهه فورًا إلى منافسة مرحة؛ وسيشارك في السباق حتمًا.'),
  ('42b47472-82e3-49e8-bb91-8de4938efbde', 'استنشقي رائحته فحسب 🫂', 'هل أفقدكِ صوابكِ اليوم حقًا واستنزف طاقتكِ بالكامل؟ لكنه ينام في سريره بكل هذه البراءة... أطفئي الأنوار. استلقي بجانبه، واستنشقي بعمق رائحة الطفولة النقية، واهمسي له بمدى غلاته عندكِ.'),
  ('67931668-7ad8-456d-8077-31b1756abd2c', 'قدّمي الماء في كوب مختلف! 🥤', 'هل قامت القيامة في الغرفة لأنكِ قدّمتِ الماء في الكوب الأصفر؟ ويقول طفلكِ: كنت أريد الأزرق! لا تبالغي في التفكير، فهو يختبر حدوده فحسب. اسكبي الماء فورًا في الكوب الأزرق، وأعيدي السلام إلى الغرفة ووفّري طاقتكِ.'),
  ('047715fd-ae66-4d00-8341-50e230c2b688', 'الديناصورات لا تأكل العصيدة! 🦖', 'ألا يجيب عن أي سؤال في الصباح، بل يزمجر فقط؟ إنه اليوم ديناصور T-Rex. سايريه في هذه الشخصية التي ابتكرها واسأليه: هل تتناول ديناصورات T-Rex وجبة الإفطار؟ وهكذا يمكنكِ إقناعه بالجلوس إلى المائدة بهدوء ومن دون دموع.'),
  ('2da52e9b-b72c-461f-8480-276d6d5e47df', 'لا تقفي حائرة وسط المتجر 🛒', 'هل دخلتِ المتجر ونسيتِ ما تريدين شراءه؟ عقل الأم مثقل فعلًا بالكثير من الأمور. افتحي قائمة التسوق في التطبيق واعتمدي على هذه الذاكرة الرقمية، فهي ستنقذكِ دائمًا من العودة إلى المنزل خالية الوفاض.'),
  ('2e1371fa-bf2b-4fc1-b3c0-c7f4619346f4', 'أطفئي الشاشات ليأتي النوم 🌙', 'لمساعدته على النوم بسرعة، أطفئي جميع شاشات التلفاز والهواتف في الغرفة قبل موعد النوم بساعة واحدة. يُفرَز الميلاتونين بسرعة في البيئة المظلمة، فدعي هذه العملية الطبيعية تعمل لصالحكِ.'),
  ('020f5f2c-bba3-4441-b9a0-518ce0263ac5', 'ليست قمامة، بل تحفة فنية 🎨', 'هل صنع في وسط الغرفة تحفة فنية كبيرة من المعكرونة الجافة وقصاصات الورق؟ ضعي هوس النظافة جانبًا. فهذا نشاط جميل للمهارات الحركية الكبرى، ويستحق تسجيله في متتبّع النمو. المنزل ليس متحفًا.'),
  ('7231bd75-47cb-4255-ae64-144dcd8d314f', 'رقم الهدوء على الشاشة 📉', 'نام أخيرًا. هل حلّ في المنزل هدوء شديد لدرجة أنكِ تسمعين طنينًا في أذنيكِ؟ افتحي مقياس الصوت في التطبيق. ستكون رؤية عبارة 0 ديسيبل أفضل تدليك بصري في العالم لعقلكِ المتعب والمنهك من الضوضاء.'),
  ('d3223299-be6e-4dfc-bfb7-c168e33bb866', 'أكملي الجمل الناقصة 🗣️', 'عندما ينسى كلمة، هل يشير بيديه وينتظر منكِ أن تعرفيها؟ تتسع حصيلته اللغوية، لكن دماغه يعمل أسرع من لسانه. أكملي جملته بصبر، وراقبي ملامح الارتياح على وجهه وهي تقول: نعم، هذا بالضبط ما كنت أقصده.'),
  ('3f9c24cf-68b9-4b5b-9e40-a3652b7d443e', 'مصارعة على الأريكة مع أبيه 🤼‍♂️', 'هل ركض واختبأ كي لا يذهب إلى السرير؟ مرّري المهمة إلى أبيه. دعيهما يتظاهران بالمصارعة على الأريكة. فهذا اللعب الصاخب الذي يجمع الأب بطفله ويجعله يتعرق سيستنزف آخر ما لديه من طاقة عنيدة، ويساعده على الاستسلام للنوم بسهولة.'),
  ('4d053e9f-b091-45c7-9c6a-66e7f1ab590e', 'فن إخفاء الخضراوات 🥦', 'هل عثر على قطعة الجزر الوحيدة في الحساء وقال: لن آكل هذا؟ اهرسي الخضراوات وأضيفيها إلى الصلصات، ولنرَ كيف سيعثر عليها هذه المرة! تغلّبي بمهارة على ذكائه في اكتشاف مكونات الطعام.'),
  ('db42b564-536c-485c-afff-dce099e8c451', 'أريد أن أطير! 🕊️', 'هل يقفز من الأريكة ويرفرف بذراعيه، ثم يغضب منكِ لأنه لا يطير؟ ما زال الوقت مبكرًا لتعليمه قوانين الفيزياء. قولي له: «أنت لا تطير لأن جناحيك ما زالا ينموان»، ووجّهي انتباهه إلى القفز على مكان طري.'),
  ('294ce10a-4fac-4bfb-8007-e2e3fea714ad', 'انتقاد رسمه بنفسه 🖍️', 'هل لم يعجبه الخط الذي رسمه، فمزّق الورقة وألقاها قائلًا: «هذا سيئ»؟ لقد بدأ لديه حس النقد الذاتي والسعي إلى الكمال! حوّلي خيبة أمله إلى تجربة استكشافية داعمة بقولكِ: «لنجرب لونًا مختلفًا في المرة القادمة».'),
  ('76df67fe-b947-400d-8825-c8fd1637478f', 'مواساة صامتة في المجتمع 💬', 'هل أنتِ متعبة جدًا لدرجة أنكِ لا ترغبين حتى في الفضفضة لأحد؟ ادخلي إلى مجتمع Anacan واكتفي بالقراءة. رؤية كيفية تعامل الأمهات الأخريات مع نوبات الغضب العبثية نفسها ستمنحكِ أقوى مواساة صامتة.'),
  ('882a14e7-4dd7-4a8b-8fa7-7bd5afe17ad2', 'عاصفة المحيط في حوض الاستحمام 🌊', 'هل الاستحمام مجرد حجة، بينما يحوّل حوض الاستحمام في الواقع إلى محيط ويلعب بالأمواج؟ دعيه يلعب. فضجيج الماء وتناثره سيبددان تلك الطاقة العنيدة التي لا تنتهي في داخله. وفي المساء سيستلقي في سريره من دون أي مقاومة.'),
  ('3e4c8054-2b97-4968-a10f-267dccb5b8c0', 'فلسفة مفاجئة في الصباح الباكر 🤔', 'هل فاجأكِ بسؤال علمي: «لماذا لا نرى الريح؟» لا تقلقي! افتحي Anacan AI واحصلي على ألطف إجابة بأسلوب قصصي يناسب فهمه في هذا العمر، ومعتمدة من أطباء الأطفال وعلماء النفس، ثم اقرئيها له. فأنتِ الأم التي تعرف كل شيء دائمًا!'),
  ('b7b7faa9-f807-43f1-bf54-6d7f963c5e32', 'مجرد الاستلقاء بهدوء 🛋️', 'هل يركّب أحجية بمفرده، وفجأة عمّ الهدوء المنزل؟ أرجوكِ، لا تضيّعي تلك اللحظة في كنس المنزل! استلقي على الأريكة. يجب أن تُشحَن بطاريتكِ أنتِ أيضًا لتتمكني من مجاراة هذه الوتيرة حتى المساء. احرصي على الراحة.'),
  ('ccae9470-c321-4925-94c0-7408317b4c14', 'كنوز تخرج من الجيوب 🪨', 'هل وجدتِ ورقة شجر جافة أو حجرًا في جيبه عند غسل سرواله؟ ليس جشعًا، بل استكشاف طفولي. ألقيه في القمامة بوجه جاد، لكن ابتسمي في داخلكِ لطفلكِ الصغير الذي يجمع المؤن؛ فهو يكتشف العالم.'),
  ('76fc525d-97d8-486f-adde-6d0bdc417bbe', 'نوبة «إنه لي!» 🧸', 'هل يحتضن جهاز التحكم في المنزل ويقول: «هذا لي!»؟ إنه يختبر حدود الملكية. لا تصفيه بالأنانية، بل قولي: «شكرًا لأنك وجدته لي»، ثم استعيديه برفق مع توجيه انتباهه إلى لعبة أخرى.'),
  ('ca5fc44a-790c-4b6a-b1b9-dcd31a3b298b', 'ننام عندما يرنّ المنبّه ⏱️', 'يستمر وقت النوم في التأخر: ماء، مرحاض، توديع الجدار... اضبطي مؤقت الهاتف، وضعي قاعدة: «عندما نسمع رنين المنبّه، يطفئ الجميع الأنوار». فتقبّل قاعدة صادرة عن جهة خارجية يكون أسهل عليهم دائمًا.'),
  ('f24ccc35-5845-4b4b-803c-db7a68218026', 'لستِ مطالبة بتبرير نفسكِ لأحد 🛑', 'هل نفد صبركِ اليوم وارتفع صوتكِ؟ لا تعاقبي نفسكِ. اكتبي في مفكرة مزاجكِ: «أنا أم جيدة، لكنني كنت متعبة جدًا اليوم». كوني رحيمة بنفسكِ؛ فلا أحد ينتظر منكِ أن تكوني مثالية.'),
  ('3fdd99bb-9e81-4b54-a9b9-28997c15bd09', 'لوح طاقة الأم 🥗', 'أعددتِ قوائم طعام متنوعة لإطعامه، لكن ماذا أكلتِ أنتِ؟ حضّري سلطة الأمهات السهلة التي لا تستغرق سوى 5 دقائق، والموجودة ضمن الوصفات الصحية.'),
  ('8e09c446-7bb4-4213-903b-ca0d9d539235', 'شاي ساخن وسط الهدوء ☕', 'نام طفلكِ أخيرًا. انظري إلى الألعاب المبعثرة كالجبل في وسط الغرفة وخذي نفسًا عميقًا. لا ترتبيها الآن! اسكبي لنفسكِ كوبًا من الشاي الساخن، واجلسي على الأريكة، واستمتعي فحسب بالسكينة التي يمنحكِ إياها هذا الهدوء.'),
  ('b85f6433-c512-4f2e-a5d4-b9023f0eb544', 'حوارات طويلة مع الجمادات 🗣️', 'هل يتحدث بمنتهى الجدية إلى حجر في الحديقة أو كرسي في المنزل؟ إنه يستوعب القواعد ويفهم العالم من خلال اللعب.'),
  ('039b7451-67d0-43b6-9ed0-d4ec9bf47752', 'رفض ارتداء المعطف 🧥', 'هل يرفض ارتداء المعطف الشتوي لأن الشمس مشرقة في الخارج؟ لا تدعي المنظر من النافذة يخدعكِ. افتحي قسم الطقس والملابس، وأريه على الهاتف رمز الطفل المرتدي ملابس شتوية. دعي الشاشة الرقمية تبلّغه بالقاعدة بدلًا منكِ.'),
  ('1d2e4dc8-5a7a-4aed-ab26-9b7c8dd5179c', 'لعبة الاختباء تحت السرير 🛏️', 'هل يصرّ على النوم تحت السرير بدلًا من النوم فيه؟ تمنحه هذه المساحات الصغيرة والمغلقة شعورًا بالأمان يشبه ما كان يشعر به في رحم أمه. اسمحي له بذلك، وبعد أن ينام ارفعيه برفق إلى السرير، ووفّري طاقتكِ.'),
  ('73a43849-8300-493d-9040-f05eaf01e5b6', 'منطق بارد كالثلج 🥶', 'هل يصرّ على وضع مكعب ثلج في الشاي الساخن بدلًا من النفخ عليه قبل شربه؟ إنه يتعلّم مفهوم التضاد بين الساخن والبارد. أعطيه الثلج ودعيه يراقب عملية ذوبانه. حتى لو تأخر الإفطار، فسيكون قد حقق اكتشافه العلمي.'),
  ('1171703b-c644-4ad0-8298-a24063264467', 'غرفة حكايات بصوت المطر 🌧️', 'هل بحّ صوتكِ ولم تعد لديكِ طاقة لقراءة حكاية؟ شغّلي في الحكايات الذكية أصوات المطر والغابة فقط كخلفية. فهذا الهدوء الطبيعي الرتيب قد يساعد أحيانًا على الاسترخاء والنوم أسرع من أفضل الحكايات وأكثرها تشويقًا.'),
  ('43e7fbfe-64bc-4627-85d6-4ddae59c6985', 'يغضب من نفسه في المرآة 🪞', 'هل يقف أمام المرآة ويصدر أصواتًا مختلفة ويرسم تعابير بوجهه؟ هذه علامة على نمو وعيه بذاته. إنه يختبر جسده وكيف تبدو مشاعره للآخرين. راقبيه بهدوء من بعيد.'),
  ('5b1cbac6-ecf8-4886-b2f1-c0e88c8559b5', 'ثورة اللمس 🔋', 'هل يتشبث بساقكِ طوال اليوم ويطلب أن تحمليه؟ أنتِ منهكة جسديًا وتعانين من إرهاق اللمس. اتركيه في الغرفة مع ألعابه واذهبي إلى الحمام لمدة 5 دقائق وأغلقي الباب. استمتعي فقط بهذه العزلة القصيرة.'),
  ('2a662eb4-1c17-46f1-ad5d-c566286402e8', 'معركة مغادرة الحديقة 🤝', 'هل دفع طفلًا آخر عند الزحليقة لأنه أراد استخدامها قبله؟ الجميع ينظر إليكِ، لكن لا تضربي طفلكِ بدافع الإحراج. ذكّريه بالقاعدة بصوت لطيف وحازم: «إنه دوره الآن، وبعده سيأتي دورنا». هكذا تسير الأمور.'),
  ('c0dcbfbe-b91a-462c-890d-a8770be19cf3', 'مطاردة في الصباح الباكر 🏃‍♂️', 'هل يركض فوق الأرائك في الساعة 7 صباحًا؟ لا تصرخي. اتركي مهامكِ لمدة 2 دقيقة وانضمي إليه في القفز. فالدخول إلى عالم طفلكِ الخيالي طريقة غريبة، لكنها فعالة جدًا أيضًا، لتخفيف توتركِ.'),
  ('e41be904-7cb3-4dd6-8966-ea3b375783f6', 'حل علمي للخوف الليلي 🔦', 'هل يخاف من ظلال غرفة النوم؟ لا تجعلي الغرفة مظلمة تمامًا، بل ضعي مصباحًا ليليًا صغيرًا بلون دافئ. فهذا لا يعطّل إفراز الميلاتونين، كما يمنحه شعورًا بالأمان البصري ويبدد خوفه.'),
  ('b5588608-ef71-4787-b05e-09f4f4f2492a', '«أحبكِ» المفاجئة 💖', 'بينما يلعب في وسط الغرفة، ينظر إليكِ فجأة ثم يركض نحوكِ ويعانقكِ. كل الليالي بلا نوم وكل التعب كان يستحق ذلك! استمتعي بهذا السلام العميق والفريد الذي تحمله هذه اللحظة، وانسي كل الفوضى.'),
  ('e2ac4132-1e14-42d5-a828-9c40ffb00179', 'القوة الغامضة للهمس 🤫', 'هل يهرب من السرير ويقفز هنا وهناك؟ اخفضي صوتكِ فجأة حتى يكاد يختفي تمامًا. ابدئي بالتحدث بصوت خافت جدًا وهمسًا. سيضطر إلى تركيز انتباهه جسديًا ليفهمكِ، وسيتعب دماغه خلال 5 دقائق وينتقل إلى وضع النوم. جرّبي!'),
  ('f5be8b0c-0a17-4790-b9b1-73d205d64a76', 'وهم أمهات إنستغرام 📱', 'هل فتحتِ إنستغرام، فرأيتِ منازل الجميع المرتبة وأطفالهن المهذبين وشعرتِ بالإحباط؟ احذفي ذلك التطبيق! انضمي إلى مجتمع Anacan، واقرئي قصص الأمهات الحقيقيات اللواتي بيوتهن فوضوية مثلكِ وأطفالهن عنيدون.'),
  ('14317db1-b6eb-40d2-8404-59bcea4acdf7', 'حكاية الأب التي تجلب النوم 📖', 'هل أُرهق صوتكِ ولم تعد لديكِ طاقة لقراءة حكاية؟ مرّري المهمة إلى الأب. فنبرة صوته المختلفة والعميقة والتفاصيل العبثية التي يختلقها ستأسر عقل طفلكِ وتغرقه في النوم أسرع من صوتكِ المألوف.'),
  ('5d28c236-3ed8-4900-b875-c6d0d9b2aa20', 'مسرحية «من أنتِ؟» 🎭', 'هل نظر إليكِ صباحًا كأنكِ غريبة وقال: «من أنتِ؟ أين أمي؟» هذه لعبة أدوار جديدة. قولي له: «أنا الخالة الجارة، وستأتي أمك حالًا». دعي الغرفة تضج بالضحك منذ الصباح؛ فهذا يوفر طاقة أكبر بكثير من الدخول في معركة عناد.'),
  ('8758179c-cc13-42d7-b2c1-4900aea35e3a', 'لن يعطيكِ من طعامه 🍳', 'لا يعطيكِ شيئًا مما في طبقه، لكنه يأتي ويصر على الأكل من طبقكِ؟ يثق الأطفال دائمًا تمامًا باختيارات والديهم. لا تقاومي؛ قدّمي له اللقمة بحب، واكتفي بالابتسام لهذه الأنانية الطريفة.'),
  ('12a06ab8-bcee-4772-8e2b-6f509250a594', 'أريد أن أطير! 🕊️', 'هل يقفز من الأريكة ويرفرف بذراعيه، ثم يغضب منكِ لأنه لم يطر؟ ما زال الوقت مبكرًا لتعليمه قوانين الفيزياء. قولي له: «أنت لا تطير لأن جناحيك ما زالا ينموان»، ثم وجّهي انتباهه إلى القفز على مكان طري.'),
  ('e80a8c85-c67a-45b2-8209-90553a33fb5f', 'لص الهاتف 📱', 'هل ذهبتِ لتسكبي لنفسكِ كوبًا من الشاي، ثم اكتشفتِ أن هاتفكِ اختفى وأنه خلف الأريكة يقول مثلكِ: «ألو»؟ إنه يقلّد عاداتكم الرقمية. عندما تأخذين الجهاز منه، قولي ضاحكة: «يبدو أن هاتفي يريد التحدث إليك أيضًا».'),
  ('ebb45c07-d4c6-4504-ac39-3e83655d3e00', 'معًا في صمت كزوجين 🥂', 'نام طفلكِ وأصبح المنزل مرتبًا. اجلسي بجوار زوجكِ على الأريكة، ولا تشغّلا حتى التلفاز. فقط تبادلا نظرة تقول: «نجحنا في هذا أيضًا، ونجونا». صدّقي أن هذه هي أكثر لحظات العمل الجماعي صدقًا في حياة الوالدين المرهقة.'),
  ('add15a56-d6d1-4819-af57-b57688cec0f4', 'النوم من دون قراءة قصة 🪄', 'ألا طاقة لديكِ لقراءة قصة هذا المساء؟ افتحي القصص الذكية، وشغّلي في الخلفية أصوات الغابة الهامسة والرياح فقط. استمعا معًا إلى أصوات الطبيعة في الظلام واستريحا من الضجيج. سيزول الإرهاق البصري في الحال.'),
  ('b000be1e-116f-4403-b926-fe4428d04231', 'كتابة الغضب الذي بداخلي 📝', 'ألا يرى أحد مدى تعبكِ في المنزل، وهذا يجعلكِ على وشك الانفجار؟ افتحي يوميات المزاج واكتبي فيها كل ما أثار غضبكِ اليوم. تقبّل مشاعركِ والتعبير عنها بالكتابة سيساعدكِ أكثر من التظاهر بالابتسام.'),
  ('f9e06d3b-098b-4aa8-b407-0f31bbbcfcf8', 'أنا أعرف، دعيني أعلّمكِ أيضًا ☝️', 'هل يأتي ليشرح لكِ شيئًا تعرفينه أصلًا، بملامح جادة وواثقة جدًا؟ إنه يختبر ذكاءه. اعضّي على شفتكِ كي لا تضحكي، لكن استمعي إليه بجدية وقولي: «حقًا؟ شكرًا جزيلًا لك». عزّزي ثقته بنفسه.'),
  ('5b3e259a-f085-41f9-b9ba-e7ff8789e89c', 'فيضان الماء في حوض الاستحمام 🌊', 'هل الاستحمام مجرد ذريعة، بينما هو في الحقيقة يصنع محيطًا في الحوض ويلعب بالأمواج؟ دعيه يلعب. فضجيج الماء ورذاذه سيساعدانه على تفريغ تلك الطاقة العنيدة التي لا تنتهي. وفي المساء سيستلقي في سريره من دون أي مقاومة.'),
  ('7c552cb2-0d81-4027-8eba-e235f8359b1d', 'يساعدكِ في المطبخ 🧑‍🍳', 'هل جاء بمقعده وأصرّ على سكب الدقيق بنفسه بينما كنتِ تفردين العجين؟ سيبكي إن لم تسمحي له. أعطيه وعاءً بلاستيكيًا صغيرًا وقليلًا من الدقيق. ستعمّ الفوضى المطبخ، لكن ملامح الطاهي الجاد على وجهه تستحق عناء التنظيف.'),
  ('86e3829d-08da-4b37-867c-0faf0ab2fa1c', 'التوقف بحيرة في وسط المتجر 🛒', 'هل وقفتِ في وسط المتجر تتساءلين: «ماذا جئتُ لأشتري؟» عقل الأم مثقل فعلًا بالكثير من الأمور. افتحي قائمة التسوق في التطبيق وثقي بهذه الذاكرة الرقمية؛ فهي ستنقذكِ دائمًا من هذه الفوضى.'),
  ('202773be-9378-4cfa-915c-7cbc9e98cdc2', 'بطاقة القميص تزعجه! 🏷️', 'هل يرفض ارتداء القميص لأن تلك البطاقة الصغيرة في الخلف توخزه كالإبرة؟ قد تكون الحساسية الحسية في هذا العمر مرهقة للغاية. لا تجادليه؛ خذي المقص واقطعي البطاقة من جذورها، وأنهي هذه الأزمة الصغيرة في ثوانٍ.'),
  ('65b5e1a3-f9ad-4e00-a2af-7ae096f9121d', 'لحظة الصمت المثالية 🛋️', 'هل اندمج في تركيب أحاجيه إلى درجة أن المنزل غرق فجأة في الصمت؟ لا تقلقي، بل اسكبي لنفسكِ فنجانًا من القهوة فورًا. لا تبدّدي تلك الدقائق الذهبية النادرة في التنظيف أو غسل الملابس؛ استغليها لإراحة روحكِ والتحديق في السقف. فأنتِ لستِ آلة.'),
  ('a86a31ee-9e29-4f41-aa7c-1edc94992d88', 'صرخة مفاجئة في منتصف الليل 😭', 'هل استيقظ طفلكِ باكيًا وعيناه مغمضتان، ولا يبدو أنه يسمعكِ؟ مرّري بكاءه عبر تحليل البكاء؛ فهذا رعب ليلي. حاولي ألّا توقظيه، بل ابقي بجانبه فقط، وأمسكي بيده وربّتي عليه برفق. سيهدأ من تلقاء نفسه ويعود إلى النوم العميق.'),
  ('5430bad3-c2db-4b2e-bb46-e51168e8dd91', 'لديكِ رسالة من Anacan 💌', 'خضراوات مخفية في وصفات صحية، ودموع سُكبت في مفكرة المزاج، ولحظات من الإنهاك... خلال هذه السنوات الـ4، أتقنتِ أصعب مهنة في العالم. لقد أصبحتِ بطلة لا تحتاج إلى أي تطبيق، وتدير الفوضى بحدسها. كنا مجرد دليل في الخلفية، أما أنتِ فمن أنجزتِ المهمة الحقيقية!'),
  ('7c7b74a0-c6ab-409c-babd-0085e345da09', 'اليوم 1460: لقد نجحنا! 🚀', 'تستيقظين صباحًا وتنظرين إليه... لقد أصبح الآن في الرابعة من عمره تمامًا! طوال 1460 يومًا، واجهتِ قلة النوم ونوبات الغضب والعناد، وربّيتِ هذا الإنسان الصغير. خلال هذه السنوات، لم تربي طفلًا فحسب، بل صنعتِ أيضًا في داخلكِ أمًا جديدة قوية لا تُقهر. لا قواعد اليوم؛ فقط احتضنيه وانظري بفخر إلى هذه المعجزة التي صنعتِها بنفسكِ.'),
  ('e37bc161-dfcf-4941-bac0-6c7cfe6f4ba2', 'الإشعار الأخير، والسكون الأخير 🌌', 'لقد نام. أطفئي الأنوار. هذا هو آخر إشعار يصلكِ من التطبيق. طوال 1460 يومًا، حاولنا أن نفهمكِ وأن نبقى إلى جانبكِ بصمت عندما كنتِ تتعبين أو تبكين أو تشعرين بأنكِ محاصرة. الآن ضعي الهاتف جانبًا. أنتِ رائعة، وأنتِ كافية. ومن الآن فصاعدًا، ستكتبين بنفسكِ، وبمفردكِ، بقية هذه القصة المذهلة. كان شرفًا لنا أن نرافقكِ في هذه الرحلة. إلى اللقاء يا ماما! ❤️'),
  ('c46434f8-d6b6-4038-89e7-8bc38a5332c2', 'سحر الحكاية الذكية 🪄', 'هل سئمتِ من الحكايات الكلاسيكية؟ اختاري موضوعًا مميزًا للحكايات الذكية، مثل مغامرات ديناصور سحري يحب تناول الخضروات.'),
  ('a57ba6d4-a9da-4163-8ddf-e60b3ee296c5', 'مجموعة الأمهات السرية 💬', 'هل عليكِ اتخاذ قرار صعب؟ (مثلًا، اختيار روضة أطفال). نصائح الأمهات ذوات الخبرة في مجتمع Anacan هي أكثر الحلول الواقعية والمجرّبة التي لن تجديها في أي كتاب.')
) AS v(id, t, b)
WHERE x.id = v.id;

-- Yoxlama: hər ikisi ~0 olmalıdır (boş-mənbə sətirləri istisna olmaqla)
SELECT
  (SELECT count(*) FROM public.pregnancy_day_notifications WHERE title_ar IS NULL) AS preg_ar_bos,
  (SELECT count(*) FROM public.mommy_day_notifications WHERE title_ar IS NULL) AS mommy_ar_bos;
